import java.util.Scanner;

public class Main {
    static final int MAXN = 300010;
    static int n, K, mod;
    static int[][] dp = new int[MAXN][20];
    static int[] cnt = new int[MAXN], mx = new int[MAXN];
    static int[] c = new int[MAXN], invC = new int[MAXN];

    static int qpow(int base, int exp) {
        long res = 1;
        long b = base;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * b) % mod;
            b = (b * b) % mod;
            exp >>= 1;
        }
        return (int) res;
    }

    static int comb(int i, int j) {
        return (int) (((long) c[i] * invC[j] % mod) * invC[i - j] % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        K = sc.nextInt();
        mod = sc.nextInt();

        int ans = 0;

        if ((n & 1) == 1) {
            System.out.println(qpow(K, n));
            sc.close();
            return;
        }

        c[0] = 1;
        for (int i = 1; i <= n; i++) {
            c[i] = (int) ((long) c[i - 1] * i % mod);
        }

        invC[n] = qpow(c[n], mod - 2);
        invC[0] = 1;
        for (int i = n - 1; i >= 1; i--) {
            invC[i] = (int) ((long) invC[i + 1] * (i + 1) % mod);
        }

        for (int i = 1; i <= n; i++) {
            int count = 0;
            for (int j = 0; j <= 18; j++) {
                if (((1 << j) & i) != 0) {
                    count++;
                }
            }
            cnt[i] = count;
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 18; j >= 0; j--) {
                if (((1 << j) & i) != 0) {
                    mx[i] = 1 << j;
                    break;
                }
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < 20; j++) {
                dp[i][j] = 0;
            }
        }
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            if ((n & i) != i) continue;
            int rem = i ^ mx[i];
            for (int mask = rem; ; mask = (mask - 1) & rem) {
                int cur = mask + mx[i];
                int c2 = i ^ cur;
                int limit = Math.min(K - 1, cnt[c2]);
                int tmpVal = comb(i, cur);
                for (int j = 0; j <= limit; j++) {
                    dp[i][j + 1] = (int) (((long) dp[i][j + 1] + (long) dp[c2][j] * tmpVal) % mod);
                }
                if (mask == 0) break;
            }
        }

        for (int j = 1; j <= Math.min(cnt[n], K); j++) {
            ans = (int) (((long) ans + (long) dp[n][j] * comb(K, j) % mod * c[j]) % mod);
        }

        ans = (qpow(K, n) - ans + mod) % mod;
        System.out.println(ans);
        sc.close();
    }
}
